INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (57, 1, 'Monitoring 과 Observability 의 차이 알기', '"Monitoring" 과 "Observability(관측 가능성)" 의 차이로 알맞은 것은 무엇일까요?', '한쪽은 "미리 정한 질문"에 답하고, 한쪽은 "정하지 않은 질문"에도 답합니다.', NULL, NULL, '[]', 'choice', '["Monitoring 은 로그만, Observability 는 메트릭만 다룬다", "둘은 같은 말이고 도구 이름만 다르다", "Monitoring 은 미리 정해 둔 질문(CPU 80% 초과 여부 등)에 답하고, Observability 는 정하지 않은 질문(왜 이 사용자만 느린가)에도 외부 출력만으로 답할 수 있어야 한다", "Observability 는 서버 안에 직접 들어가서 디버깅하는 것이다"]', 2, 'Monitoring 은 "알고 있는 것을 확인"하는 것이고, Observability 는 "모르는 것을 알아내는" 것에 가깝습니다. 장애 원인은 매번 달라서 사전에 대시보드로 다 준비할 수 없기 때문에, 시스템 **외부로 나오는 출력(Trace·Metric·Log)** 만으로 내부 상태를 추론할 수 있어야 한다는 개념입니다.', NULL, NULL, NULL, NULL),
  (57, 2, '설명에 해당하는 신호 고르기 (1)', '**요청 하나**가 여러 컴포넌트를 거쳐 흘러간 전체 경로와 구간별 소요 시간입니다. "이 요청이 **어디서 느려졌는가**" 에 답합니다. 어떤 신호(signal)일까요?', 'Trace, Metric, Log 중 "요청 하나의 경로" 를 다루는 것입니다.', NULL, NULL, '[]', 'choice', '["Trace", "Metric", "Log", "Profile"]', 0, '**Trace** 는 요청 하나의 전체 경로이고, 여러 컴포넌트에서 생긴 span 들이 모여 하나의 trace 를 이룹니다. **Metric** 은 시간에 따라 집계된 수치("지금 전반적으로 어떤가"), **Log** 는 특정 시점의 독립된 사건 기록("그 순간 정확히 무슨 일이 있었는가") 입니다.', NULL, NULL, NULL, NULL),
  (57, 3, '설명에 해당하는 신호 고르기 (2)', '특정 시점에 발생한, 서로 이어지지 않고 **툭툭 남는 개별 사건의 기록**입니다. "그 순간 정확히 무슨 일이 있었는가" 에 답합니다. 어떤 신호일까요?', '시간에 따라 집계한 숫자도, 요청의 경로도 아닙니다.', NULL, NULL, '[]', 'choice', '["Trace", "Log", "Metric", "Span"]', 1, '**Log** 는 개별 사건 기록입니다. OpenTelemetry 는 Trace·Metric·Log 를 **signal** 이라는 공통 개념으로 묶어 같은 파이프라인으로 다룹니다. 같은 trace id 를 로그와 span 에 함께 남기면 로그를 보다가 그 요청의 전체 경로로 넘어갈 수 있습니다.', NULL, NULL, NULL, NULL),
  (57, 4, 'Prometheus 의 수집 방향 알기', 'Prometheus 가 메트릭을 수집하는 방식으로 알맞은 것은 무엇일까요?', '"scrape" 라는 말을 떠올려 보세요. 누가 누구를 긁어 올까요?', NULL, NULL, '[]', 'choice', '["Prometheus 가 대상의 `/metrics` HTTP 엔드포인트를 주기적으로 **직접 긁어 온다** (pull 모델)", "대상이 Prometheus 로 데이터를 밀어 넣는다 (push 모델)", "Kafka 를 거쳐서만 수집한다", "로그 파일을 읽어서 숫자로 바꾼다"]', 0, 'Prometheus 는 **pull** 모델입니다. 수집 주기를 Prometheus 가 통제하고, scrape 가 실패하면 대상이 죽었음을 바로 알 수 있습니다. 대상 앱은 `/metrics` 만 노출하면 되고 모니터링 서버의 위치를 몰라도 됩니다.', NULL, NULL, NULL, NULL),
  (57, 5, '메트릭을 식별하는 방법 알기', 'Prometheus 에서 `http_requests_total{method="GET", code="200"}` 과 `http_requests_total{method="GET", code="500"}` 은 어떤 관계일까요?', '메트릭은 이름과 레이블의 **조합**으로 식별됩니다.', NULL, NULL, '[]', 'choice', '["같은 시계열이고 값만 다르다", "이름은 같지만 레이블 조합이 달라 **서로 다른 시계열**이다", "둘 다 `GET` 이므로 하나로 합쳐 저장된다", "레이블이 달라도 오류 없이 덮어쓴다"]', 1, '시계열은 **메트릭 이름 + 레이블 집합**으로 식별되고, 레이블 하나만 달라도 별개의 시계열입니다. 이 다차원 모델 덕분에 메트릭 이름을 늘리지 않고도 레이블로 필터링·집계할 수 있습니다. (레이블 조합이 너무 많이 늘어나는 것이 카디널리티 문제입니다.)', NULL, NULL, NULL, NULL),
  (57, 6, 'Prometheus 가 샘플을 저장하는 흐름 놓기', 'scrape 한 샘플이 Prometheus 내장 TSDB 에 저장되어 오래된 구간으로 정리되는 흐름을 **앞에서 뒤 순서**대로 놓으세요.', '서버가 죽어도 복구할 수 있도록 디스크에도 동시에 적어 둡니다.', NULL, NULL, '[]', 'order', '["약 2시간마다 디스크의 불변 Block 으로 내려간다", "샘플이 Head(메모리)에 쓰이면서 동시에 WAL(디스크 로그)에도 적힌다", "Block 들이 compaction 으로 더 큰 Block 으로 합쳐진다", "대상을 scrape 해서 샘플을 받는다"]', NULL, '**scrape → Head(메모리) + WAL(디스크 로그) 동시 기록 → 약 2시간마다 Block → compaction** 순서입니다. 서버가 죽으면 재시작할 때 WAL 을 재생해서 Head 를 복구합니다. 보관 기간이 길어지면 로컬 디스크 용량 문제가 생기는데, 이를 푸는 것이 Thanos 입니다.', '[3, 1, 0, 2]', NULL, NULL, NULL),
  (57, 7, 'Thanos 가 하는 일 알기', '"Thanos 가 메트릭을 수집한다" 는 말은 정확할까요? Thanos 의 역할로 알맞은 것은 무엇일까요?', '실제로 타겟을 scrape 하는 것은 누구일까요?', NULL, NULL, '[]', 'choice', '["Thanos 가 Prometheus 를 대체해서 직접 타겟을 scrape 한다", "Thanos 는 로그를 저장하는 시스템이다", "수집은 여전히 각 Prometheus 가 하고, Thanos 는 오래된 데이터를 오브젝트 스토리지(S3 등)로 내보내 **장기 보관**하고 여러 Prometheus 의 데이터를 **조회 시점에 하나로 합쳐** 준다", "Thanos 는 알림 메일을 보내는 도구이다"]', 2, 'Prometheus 는 단일 노드 설계라 (1) 로컬 디스크 때문에 장기 보관이 어렵고 (2) 인스턴스가 여러 개면 각각 따로 조회해야 합니다. Thanos 는 이 두 가지를 풀어 주지만 **수집을 대체하지는 않습니다.** 실제 scrape 는 계속 각 Prometheus 가 합니다.', NULL, NULL, NULL, NULL),
  (57, 8, 'ServiceMonitor 의 역할 알기', '쿠버네티스에서 Prometheus Operator 를 쓸 때 **ServiceMonitor** 는 무엇일까요?', '"어떤 앱의 메트릭을 읽을지" 를 적어 두는 문서를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["메트릭을 저장하는 데이터베이스", "알림을 보내는 서비스", "메트릭을 그래프로 그려 주는 화면", "Prometheus 가 어느 네임스페이스에서 어떤 라벨의 Service 의 어느 이름의 포트를 읽을지 적어 두는 **안내서(CRD)**"]', 3, 'ServiceMonitor 는 Prometheus Operator 가 등록하는 **CRD** 입니다. 네임스페이스, Service 라벨, 포트 이름 세 가지를 적어 두면 Operator 가 읽어서 Prometheus 의 수집 설정에 반영하고, Prometheus 는 해당 Pod 를 주기적으로 scrape 합니다.', NULL, NULL, NULL, NULL),
  (57, 9, 'Loki 가 로그를 저장하는 방식 알기', 'Loki 는 Elasticsearch 와 달리 로그를 **싸게** 저장합니다. 비결은 무엇일까요?', '"로그를 위한 Prometheus" 라는 별명이 힌트입니다. Prometheus 는 무엇으로 시계열을 식별하나요?', NULL, NULL, '[]', 'choice', '["로그를 저장하지 않고 요약본만 남긴다", "로그 본문 전체가 아니라 **레이블(namespace, pod, app 등)만 인덱싱**하고, 레이블로 좁힌 로그 스트림 안에서 grep 방식으로 검색한다", "로그 본문의 모든 단어에 역색인을 만든다", "로그를 모두 메모리에만 둔다"]', 1, 'Elasticsearch 는 본문 전체에 풀텍스트 인덱스를 만들어 저장 비용과 인덱스 크기가 큽니다. Loki 는 **레이블만 인덱싱**하고 LogQL(PromQL 과 유사)로 스트림을 좁힌 뒤 안에서 검색합니다. 그래서 수집 단계에서 레이블을 어떻게 붙이느냐가 중요합니다.', NULL, NULL, NULL, NULL),
  (57, 10, '설명에 해당하는 수집 에이전트 고르기', '**로그, 메트릭, 트레이스**를 하나의 에이전트·하나의 파이프라인으로 처리하는 Grafana Labs 의 통합 수집 에이전트입니다. 로그만 읽어 Loki 로 보내던 Promtail 의 역할도 대신하며 새로 구성할 때 권장됩니다. 무엇일까요?', '로그 전용인 Promtail 과 달리 여러 신호를 한꺼번에 다룹니다.', NULL, NULL, '[]', 'choice', '["Grafana Alloy", "Promtail", "Logstash", "Thanos"]', 0, '**Alloy** 는 Grafana Agent 의 후속으로 로그·메트릭·트레이스를 한 에이전트에서 처리합니다. **Promtail** 은 로그 전용(노드의 로그 파일을 읽어 레이블을 붙여 Loki 로 push), **Logstash** 는 Elastic Stack 의 파이프라인 도구, **Thanos** 는 Prometheus 확장 레이어입니다.', NULL, NULL, NULL, NULL),
  (57, 11, 'Logstash 와 Vector 구분하기', '다음 설명에 해당하는 도구는 무엇일까요? **Rust** 로 작성되어 메모리를 적게 쓰고 정적 바이너리 하나로 배포되며, **source → transform → sink** 구조로 **로그와 메트릭을 모두** 다룹니다. 변환에는 자체 언어 VRL 을 씁니다.', 'Logstash 는 input → filter → output 구조이고 Elastic Stack 의 일부입니다.', NULL, NULL, '[]', 'choice', '["Logstash", "Loki", "Vector", "Prometheus"]', 2, '**Vector** 는 source → transform(VRL) → sink 구조이고 로그뿐 아니라 메트릭도 정상적인 용도입니다(예: Prometheus 메트릭을 Kafka 로 넘기기). **Logstash** 는 input → filter(Grok 등) → output 구조로 Elasticsearch 로 보내는 것이 흔합니다.', NULL, NULL, NULL, NULL),
  (57, 12, 'Loki 로 로그가 흘러가는 순서 놓기', '쿠버네티스 노드의 컨테이너 로그가 Grafana 화면까지 오는 흐름을 **앞에서 뒤 순서**대로 놓으세요.', '로그를 만들어 내는 쪽에서 보여 주는 쪽 순서입니다.', NULL, NULL, '[]', 'order', '["Loki 가 레이블과 함께 로그를 저장한다", "컨테이너가 로그 파일을 남긴다", "Grafana 가 LogQL 로 Loki 를 조회해 보여 준다", "Promtail(또는 Alloy)이 로그를 읽어 레이블을 붙여 Loki 로 push 한다"]', NULL, '**컨테이너 로그 파일 → Promtail/Alloy 가 읽어 레이블을 붙여 push → Loki 저장(레이블 인덱싱) → Grafana 가 LogQL 로 조회** 순서입니다. 이 흐름에서 레이블을 붙이는 단계(수집 에이전트 설정)가 이후 검색 품질을 좌우합니다.', '[1, 3, 0, 2]', NULL, NULL, NULL);
